        return;
    }
    visited[i][j] = true;
    markOilDeposit(grid, visited, i - 1, j);
    markOilDeposit(grid, visited, i + 1, j);
    markOilDeposit(grid, visited, i, j - 1);
    markOilDeposit(grid, visited, i, j + 1);
}
