public static int countOilDeposits(char[][] grid) {
    if (grid.length == 0) {
        return 0;
    }

    int deposits = 0;
    Set<Integer> visited = new HashSet<>();

    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@' && !visited.contains(i * grid[i].length + j)) {
                dfs(grid, i, j, visited);
                deposits++;
            }
        }
    }

    return deposits;
}

private static void dfs(char[][] grid, int i, int j, Set<Integer> visited) {
    visited.add(i * grid[i].length + j);

    // Check neighbors
    if (i > 0 && grid[i - 1][j] == '@' && !visited.contains((i - 1) * grid[i - 1].length + j)) {
        dfs(grid, i - 1, j, visited);
    }
    if (i < grid.length - 1 && grid[i + 1][j] == '@' && !visited.contains((i + 1) * grid[i + 1].length + j)) {
        dfs(grid, i + 1, j, visited);
    }
    if (j > 0 && grid[i][j - 1] == '@' && !visited.contains(i * grid[i].length + j - 1)) {
        dfs(grid, i, j - 1, visited);
    }
    if (j < grid[i].length - 1 && grid[i][j + 1] == '@' && !visited.contains(i * grid[i].length + j + 1)) {
        dfs(grid, i, j + 1, visited);
    }
}
