```java
package io.ray.streaming.api.function;

import io.ray.streaming.api.context.RuntimeContext;

import java.util.HashMap;
import java.util.Map;

/**
 * A RichFunction implementation for counting the frequency of words in a stream of text data.
 */
public class WordCountFunction implements RichFunction {
    private Map<String, Integer> wordCounts;

    public WordCountFunction() {
        wordCounts = new HashMap<>();
    }

    @Override
    public void open(RuntimeContext runtimeContext) {
        // Initialize resources if needed
    }

    @Override
    public void close() {
        // Clean up resources if needed
    }

    /**
     * Processes a string of text and updates the word count.
     *
     * @param text the input text to process
     */
    public void countWords(String text) {
        String[] words = text.toLowerCase().split("\\s+");
        for (String word : words) {
            wordCounts.put(word, wordCounts.getOrDefault(word, 0) + 1);
        }
    }

    /**
     * Returns the current word count.
     *
     * @return a map of words to their corresponding counts
     */
    public Map<String, Integer> getWordCount() {
        return wordCounts;
    }
}

