```java
import java.util.Arrays;

public class WordRearranger {

    /**
     * Rearranges an array of words according to the given pattern and returns the resulting sentence.
     * 
     * @param words   The array of words to be rearranged.
     * @param pattern The pattern string indicating the order of indices.
     * @return The rearranged sentence or an error message if the pattern is invalid.
     */
    public static String rearrangeWords(String[] words, String pattern) {
        String[] indices = pattern.split(" ");
        StringBuilder sentence = new StringBuilder();

        for (String indexStr : indices) {
            try {
                int index = Integer.parseInt(indexStr);
                if (index < 0 || index >= words.length) {
                    return "Error: Index " + index + " is out of bounds for the array of words.";
                }
                sentence.append(words[index]).append(" ");
            } catch (NumberFormatException e) {
                return "Error: Pattern contains an invalid number '" + indexStr + "'.";
            }
        }

        return sentence.toString().trim();
    }

    public static void main(String[] args) {
        String[] words = {"Java", "Saturday", "day", "coding", "is"};
        String pattern = "1 4 0 3 2";
        System.out.println(rearrangeWords(words, pattern)); // Expected: "Saturday is Java coding day"

        // Test cases
        String patternWithOutOfBoundsIndex = "1 4 0 five 2";
        System.out.println(rearrangeWords(words, patternWithOutOfBoundsIndex)); // Expected error message

        String patternWithInvalidNumber = "1 4 0 thirteen 2";
        System.out.println(rearrangeWords(words, patternWithInvalidNumber)); // Expected error message
    }
}
```

