private static boolean dfs(int[] current, int[] end, boolean[][] visited, int[][] paths) {
  // If the current n-tersection is the ending n-tersection, return true
  if (current[0] == end[0] && current[1] == end[1]) {
    return true;
  }

  // Mark the current n-tersection as visited
  visited[current[0]][current[1]] = true;

  // Loop through all possible next n-tersections
  for (int[] next : paths[current[0]][current[1]]) {
    // Check if the next n-tersection is already visited
    if (!visited[next[0]][next[1]]) {
      // If the next n-tersection is not visited, mark it as visited and recurse
      visited[next[0]][next[1]] = true;
      if (dfs(next, end, visited, paths)) {
        return true;
      }
    }
  }

  // If all possible next n-tersections have been visited, return false
  return false;
}
