public int search(int[] nums, int target) {
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        int num = nums[mid];
        if (num == target) {
            return mid;
        } else if (nums[left] <= nums[mid]) { // Left part is sorted
            if (target >= nums[left] && target < nums[mid]) { // Target is in left part
                right = mid - 1;
            } else { // Target is in right part
                left = mid + 1;
            }
        } else { // Right part is sorted
            if (target > nums[mid] && target <= nums[right]) { // Target is in right part
                left = mid + 1;
            } else { // Target is in left part
                right = mid - 1;
            }
        }
    }
    return -1;
}
