public String sortString(String s) {
    // Convert the string to a char array for easier manipulation
    char[] chars = s.toCharArray();

    // Sort the array in ascending order
    Arrays.sort(chars);

    // Initialize variables to keep track of the smallest and largest characters
    char smallest = chars[0];
    char largest = chars[chars.length - 1];

    // Initialize a string builder to build the result
    StringBuilder result = new StringBuilder();

    // Loop until all characters have been used
    while (result.length() < chars.length) {
        // Append the smallest character to the result
        result.append(smallest);

        // Update the smallest character to be the next smallest character
        smallest = chars[0];
        for (int i = 1; i < chars.length; i++) {
            if (chars[i] < smallest) {
                smallest = chars[i];
            }
        }

        // Append the largest character to the result
        result.append(largest);

        // Update the largest character to be the next largest character
        largest = chars[chars.length - 1];
        for (int i = chars.length - 2; i >= 0; i--) {
            if (chars[i] > largest) {
                largest = chars[i];
            }
        }
    }

    return result.toString();
}
