public String sortString(String s) {
    char[] charArray = s.toCharArray();
    List<Character> result = new ArrayList<>();
    while (result.size() < s.length()) {
        int minIndex = findMinIndex(charArray);
        int maxIndex = findMaxIndex(charArray);
        if (minIndex != -1) {
            result.add(charArray[minIndex]);
            charArray[minIndex] = '\0';
        }
        if (maxIndex != -1) {
            result.add(charArray[maxIndex]);
            charArray[maxIndex] = '\0';
        }
    }
    return String.valueOf(result.toArray(new char[0]));
}

private int findMinIndex(char[] arr) {
    int minIndex = -1;
    char minValue = Character.MAX_VALUE;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] < minValue && arr[i] != '\0') {
            minValue = arr[i];
            minIndex = i;
        }
    }
    return minIndex;
}

private int findMaxIndex(char[] arr) {
    int maxIndex = -1;
    char maxValue = Character.MIN_VALUE;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] > maxValue && arr[i] != '\0') {
            maxValue = arr[i];
            maxIndex = i;
        }
    }
    return maxIndex;
}
