public int minCostClimbingStairs(int[] cost) {
  int n = cost.length;
  int[] dp = new int[n + 1];
  dp[0] = 0;
  dp[1] = 0;
  for (int i = 2; i <= n; i++) {
    dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
  }
  return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    return recursive(cost, 0, 0);
}

private int recursive(int[] cost, int i, int accumulatedCost) {
    if (i >= cost.length) {
        return 0;
    }

    // recursive call with i + 1, accumulating the cost
    int cost1 = recursive(cost, i + 1, accumulatedCost + cost[i]);

    // if i is not the last index, recursive call with i + 2, not accumulating the cost
    int cost2 = recursive(cost, i + 2, accumulatedCost);

    return Math.min(cost1, cost2);
}

