public int uniqueMorseRepresentations(String[] words) {
    Map<String, Integer> transformedWords = new HashMap<>();
    for (String word : words) {
        String transformedWord = getMorseCode(word);
        if (!transformedWords.containsKey(transformedWord)) {
            transformedWords.put(transformedWord, 1);
        } else {
            transformedWords.put(transformedWord, transformedWords.get(transformedWord) + 1);
        }
    }
    return transformedWords.size();
}

private String getMorseCode(String word) {
    String morseCode = "";
    for (char c : word.toCharArray()) {
        morseCode += getMorseCode(c);
    }
    return morseCode;
}

private String getMorseCode(char c) {
    switch (c) {
        case 'a': return ".-";
        case 'b': return "-...";
        case 'c': return "-.-.";
        // ...
        case 'z': return "--..";
        default: return "";
    }
}

