private static String reverse(String word) {
    StringBuilder reversed = new StringBuilder(word);
    int start = 0;
    while (start < reversed.length()) {
        char current = reversed.charAt(start);
        reversed.setCharAt(start, reversed.charAt(reversed.length() - 1 - start));
        reversed.setCharAt(reversed.length() - 1 - start, current);
        start++;
    }
